"use client";
import React, { useState } from "react";
import Image from "next/image";
import Link from "next/link";
import { useRouter } from "next/navigation";
import CartModal from "./CartModal";
const basePath = process.env.NODE_ENV === 'production' ? '/VIBEFIT' : '';

export default function NavIcons() {
  const [isProfileOpen, setIsProfileOpen] = useState(false);
  const [isCartOpen, setIsCartOpen] = useState(false);

  const router = useRouter();

  // TEMPORARY
  const isLoggedIn = false;

  const handleProfile = () => {
    if (!isLoggedIn) {
      router.push("/login");
    }
    setIsProfileOpen((prev) => !prev);
  };

  return (
    <div className="flex items-center gap-4 xl:gap-6 relative">
      <button onClick={handleProfile} className="cursor-pointer">
        <Image
          src={`${basePath}/images/profile.jpg`}
          alt=""
          width={22}
          height={22}
        />
      </button>
      {isProfileOpen && (
        <div className="absolute p-4 rounded-md top-12 left-0 text-sm shadow-[0_3px_10px_rgb(0,0,0,0.2)] z-20">
          <Link href="/">Profile</Link>
          <div className="mt-2 cursor-pointer">Logout</div>
        </div>
      )}
      <Image
        src={`${basePath}/images/notification.png`}
        alt=""
        width={22}
        height={22}
        className="cursor-pointer"
      />
      <div className="relative">
        <button onClick={() => setIsCartOpen((prev) => !prev)}>
          <Image
          src={`${basePath}/images/cart.png`}
          alt=""
          width={22}
          height={22}
        />
        </button>
      <div className="absolute -top-4 -right-4 w-6 h-6 bg-[#F35C7A] rounded-full text-white text-sm flex items-center justify-center ">2</div>
      </div>
      {isCartOpen && <CartModal/>}
    </div>
  );
}
